nginx:
server {
    <span class="k">listen</span> 443 ssl;
    <span class="k">http2</span> on;
    <span class="k">server_name</span> _;
    <span class="k">ssl_certificate</span>     /etc/nginx/certs/fullchain.pem;
    <span class="k">ssl_certificate_key</span> /etc/nginx/certs/privkey.pem;
    <span class="k">ssl_protocols</span> TLSv1.2 TLSv1.3;

    <span class="k">add_header</span> Strict-Transport-Security <span class="s">&quot;max-age=31536000&quot;</span> always;
    <span class="k">add_header</span> X-Content-Type-Options nosniff always;
    <span class="k">add_header</span> X-Frame-Options SAMEORIGIN always;
    <span class="k">add_header</span> Referrer-Policy strict-origin-when-cross-origin always;
    <span class="c"># + gzip, кэш статики, /api/ → контейнер API</span>
}
